pub enum Value {
    True,
    False,
    Unknown,
}

impl Value {
    pub fn and(self, other: Value) -> Value {
        match (self, other) {
            (Value::False, _) | (_, Value::False) => Value::False,
            (Value::Unknown, _) | (_, Value::Unknown) => Value::Unknown,
            (Value::True, Value::True) => Value::True,
        }
    }
